const escape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const templates=Object.keys(messages).filter(key=>/\{\d+\}/.test(key)).sort((a,b)=>b.replace(/\{\d+\}/g,'').length-a.replace(/\{\d+\}/g,'').length).map(key=>{
 const indices=[];let pattern='',last=0;
 for(const match of key.matchAll(/\{(\d+)\}/g)){pattern+=escape(key.slice(last,match.index))+'(.+?)';indices.push(Number(match[1]));last=match.index+match[0].length}
 return {key,indices,pattern:new RegExp('^'+pattern+escape(key.slice(last))+'$')};
});
const countTemplates=new Set(['{0} changes','{0} conflicts remaining','{0} results / {1} commits','{0} commits','{0} uncommitted changes → Open Changes','Expand {0} unchanged lines','Commit staged changes · {0} files','{0} repositories','Commit only the {0} staged files.','Resolve {0} conflicts first.']);
function singularize(language,key,text){
 if(!countTemplates.has(key))return text;
 const forms=language==='es'?{cambios:'cambio',conflictos:'conflicto',resultados:'resultado',commits:'commit',líneas:'línea',archivos:'archivo',repositorios:'repositorio'}:language==='fr'?{modifications:'modification',conflits:'conflit',résultats:'résultat',commits:'commit',lignes:'ligne',fichiers:'fichier',dépôts:'dépôt'}:{};
 return text.replace(/\b1 (\p{L}+)/gu,(match,noun)=>forms[noun]?'1 '+forms[noun]:match);
}
function translate(language,text){
 const column=columns.indexOf(language);if(column<0)return text;
 if(messages[text])return messages[text][column];
 if(text.startsWith('◌ '))return '◌ '+translate(language,text.slice(2));
 if(text.startsWith('Commit only the ')&&text.includes('. '))return text.split(/(?<=\.) /).map(part=>translate(language,part)).join(' ');
 for(const {key,indices,pattern} of templates){const match=text.match(pattern);if(!match)continue;const values={};indices.forEach((index,i)=>values[index]=match[i+1]);
  // Search-field names and action labels are UI copy; branch names, paths and hashes are not.
  if(key==='{0} search'||key==='{0} completed')values[0]=messages[values[0]]?.[column]||values[0];
  return singularize(language,key,messages[key][column].replace(/\{(\d+)\}/g,(_,index)=>values[index]));
 }
 return text;
}
window.PgitLocales={languages,columns,messages,translate};
